//! River's window management protocols, as server code generated from the
//! interfaces in `protocols/` (see that directory's files for where they come
//! from). A window manager written for river binds these.

#![allow(
    missing_docs,
    clippy::all,
    reason = "generated by wayland-scanner from the protocol's interface"
)]

/// `river_window_management_v1`: the window manager, its windows, outputs,
/// seats and nodes.
pub(crate) mod window_management {
    use smithay::reexports::wayland_server;
    use smithay::reexports::wayland_server::protocol::*;

    pub(crate) mod __interfaces {
        use smithay::reexports::wayland_server::protocol::__interfaces::*;
        wayland_scanner::generate_interfaces!("protocols/river-window-management-v1.xml");
    }
    use self::__interfaces::*;

    wayland_scanner::generate_server_code!("protocols/river-window-management-v1.xml");
}

/// `river_xkb_bindings_v1`: key bindings for that window manager.
pub(crate) mod xkb_bindings {
    use smithay::reexports::wayland_server;

    pub(crate) use super::window_management::river_seat_v1;

    pub(crate) mod __interfaces {
        use super::super::window_management::__interfaces::*;
        wayland_scanner::generate_interfaces!("protocols/river-xkb-bindings-v1.xml");
    }
    use self::__interfaces::*;

    wayland_scanner::generate_server_code!("protocols/river-xkb-bindings-v1.xml");
}
